// fp kernel square root by Karp-Markstein on the reciprocal square root (contract: src/fp/kernel.hpp). The entry
// src/fp/x86_64/sqrt.S (generated by tools/generate_fp_sqrt.py) calls sbn3f_sqrt_km(z, X, n, k, c, s) with the decoded
// radicand, as it calls the IFMA block root sbn3f_sqrt_qv (div_qv.cpp) in that root's band; k <= 512.
//
// Grid. t = X 2^c / B^n in [1/4, 1), s = c/2 + 32 odd (odd = [e odd]): the target T = sqrt(t) B^K / 2^s = sqrt(x) B^K for
// x = X B^(-n-odd), the fx {X, -odd, n} (x in [B^(-1-odd), B^-odd)); T lies in [B^(K-1), B^K). h = ceil(K/2) + 2:
//   y    = rsqrt(x) at grid 1 - h:   |y - 1/sqrt x| < 4 B^(1-h)                                       (sbn3f_rsqrt)
//   s0   = x y at grid g = e_x + e_y - h = 1 - odd - h (y's exponent e_y = 1), its top h limbs when the product is a full
//          one (a short x): |s0 - x y| < 5 B^g;  d = sqrt x - s0, |d| < 4 x B^(1-h) + 5 B^g <= 9 B^(1-h) (odd = 0),
//          9 B^-h (odd = 1)
//   r    = x_t - s0^2, exact on s0^2's grid 2g (x_t: x truncated there, 0 <= x - x_t < B^2g)
//   corr = y r at grid -K-1:         < 4 units of B^(-K-1), so corr / 2 (= y r / 2) < 2 of them
//   z    = s0 + corr / 2 on grid -K (s0 exact there; corr / 2 cut to the grid: < 1 unit), clamped into
//          [B^(K-1), B^K - 1] (T lies there: a clamp moves z towards T)
// Error in units of B^-K (2h >= K + 3). s0 + (x - s0^2) / (2 sqrt x) = sqrt x - d^2 / (2 sqrt x): d^2 / (2 sqrt x) <=
// 40.5 B^(2.5-2h+K) (odd = 0, sqrt x >= B^-1/2) or 40.5 B^(1-2h+K) (odd = 1, sqrt x >= B^-1): < 2^-26. y in place of
// 1/sqrt x: |x - s0^2| |y/2 - 1/(2 sqrt x)| <= (2 sqrt x |d| + d^2) 2 B^(1-h) <= 37 B^(2-2h+K) <= 37 / B. x_t: (x - x_t) y / 2
// <= B^(2.5-2h+K) / 2 (odd = 0, y <= B^1/2) or B^(1-2h+K) / 2 (odd = 1, y <= B): < 2^-32. corr / 2: < 2 / B. The cut: < 1.
// So |z - T| < 1 + 2^-25, inside the contract's 4 units. s0's own error needs no term: the exact residual of that s0
// corrects it. |r| <= 2 sqrt x |d| + d^2 + B^2g < B^(2-h): r is computed on positions 2g .. 2 - h only (the higher limbs of
// x_t and s0^2 agree), and corr's high-product k = e_y + e_r + K + 1 <= K + 4 - h <= h, y's limbs: never a full product. The products run on the fp S entries
// (src/fp/x86_64/mul.S) where their windows fit (<= 234 limbs), on the M entries (mul_glue.cpp, a Frame on this stack)
// above.
#include "fp/kernel.hpp"
#include "core/x86_64/word.hpp"
#include "runtime/scratch.hpp"
#include <string.h>

// KM_COUNT builds (the gate's coverage of the rare paths) count them; normal builds compile the counts away
#ifdef KM_COUNT
extern "C" { long sbn3f_sqrt_km_cnt[10]; }
#define KM_CNT(i) (++sbn3f_sqrt_km_cnt[i])
#else
#define KM_CNT(i) ((void)0)
#endif

namespace fp = sbn::v3::fp;
using fp::fx;
using fp::fxr;
using fp::limb;

namespace {

constexpr int64_t SMAX = 234;                          // the S entries' window bound
constexpr int64_t KMAX = 512, HMAX = KMAX / 2 + 2;

int64_t window(const fp::mulshape &m) noexcept { return m.full ? (m.ka > m.kb ? m.ka : m.kb) : m.k; }

// a b (&b == &a: a square) at grid L into z (the S entry when its windows fit, else the M entry on f)
fxr product(limb *z, const fx &a, const fx &b, int64_t L, sbn::v3::Frame &f) noexcept {
    const int64_t leps = 64 * L + 2;
    if (window(fp::mul_shape(a, b, leps)) <= SMAX) return &a == &b ? sbn3f_sqr(z, &a, leps) : sbn3f_mul(z, &a, &b, leps);
    return &a == &b ? fp::sqr_m(z, a, leps, f) : fp::mul_m(z, a, b, leps, f);
}

// the M entries' Frame bytes for this K (0 when every window fits the S entries): s0 and corr are high products of
// k <= h + 1 (corr: e_y + e_rh + K + 1 with e_y <= 1, e_rh <= 2 - h), the square a full product of at most h + 1 limbs
size_t m_bytes(int64_t h) noexcept {
    if (h + 1 <= SMAX) return 0;
    const fx a{nullptr, 1, uint64_t(h + 1)}, q{nullptr, 1, uint64_t(h + 1)};
    const size_t b1 = fp::mul_m_need(a, a, 64 * (1 - h) + 2).bytes;          // k = h + 1, high shape
    const size_t b2 = fp::sqr_m_need(q, 64 * (2 - 2 * (h + 1)) + 2).bytes;    // full shape, h + 1 limbs
    return b1 > b2 ? b1 : b2;
}

} // namespace

extern "C" void sbn3f_sqrt_km(limb *z, const limb *X, uint64_t n, uint64_t k, unsigned c, unsigned s) noexcept {
    const int64_t K = int64_t(k), N = int64_t(n), h = (K + 5) / 2, odd = int64_t(s - (c >> 1)) >> 5;
    // y h limbs; s0 / corr: the M entries' 2k + 2 <= 2h + 4 limbs; q 2h; r w <= h + 5; x's window (short x) w
    limb Y[HMAX], S0[2 * HMAX + 4], Q[2 * HMAX + 4], R[HMAX + 8], XT[HMAX + 8], C[2 * HMAX + 4];
    const size_t fb = m_bytes(h);
    void *fbuf = fb ? __builtin_alloca_with_align(fb, 512) : nullptr;
    sbn::v3::Frame f = sbn::v3::Frame::external(fbuf, fb);
    const fx x{X, -odd, n};
    if (fb) KM_CNT(0);                                                       // 0: M entries (h + 1 > 234)

    const fxr ry = sbn3f_rsqrt(Y, &x, 64 * (1 - h) + 2);
    const fx y{Y, ry.e, ry.ns};
    const fxr rs = product(S0, x, y, x.e + y.e - h, f);
    int64_t n0 = fp::len(rs.ns);
    const limb *s0d = S0;
    if (n0 > h) s0d += n0 - h, n0 = h;                                     // a full product (short x): its top h limbs
    const int64_t g0 = rs.e - n0;                                          // s0 = s0d[0..n0) at grid g0
#ifdef KM_FORCE
    {   // the gate's forced build: s0 + 3 units (|d| grows by 3 B^g0, inside the bound's slack), so r < 0 is common;
        // not where the low limb would carry (all-ones s0: the edge families keep their natural path)
        limb *m = S0 + (s0d - S0);
        if (m[0] <= ~limb(3)) m[0] += 3;
    }
#endif
    const fx s0{s0d, rs.e, uint64_t(n0)};
    const fxr rq = product(Q, s0, s0, 2 * g0, f);                           // exact: the full shape, M = n0 <= k = 2 n0
    const int64_t nq = fp::len(rq.ns), gq = rq.e - nq;                      // gq = 2 g0

    // r = x_t - q on positions gq .. 2 - h only: |r| < B^(2-h) (above), so these w limbs hold r in two's complement, the
    // top one 0 or ~0 (the higher positions of x_t and q agree). x's limbs there: X[j0 + i], zeros below a short X.
    const int64_t w = 3 - h - gq, j0 = gq + N + odd;
    const limb *xw = X + j0;
    if (j0 < 0) {                                                            // 1: a short x
        KM_CNT(1);
        for (int64_t i = 0; i < w; ++i) XT[i] = j0 + i >= 0 ? X[j0 + i] : 0;
        xw = XT;
    }
    if (nq >= w) sbn3i_sub_n(R, xw, Q, long(w));
    else {                                                                   // 2: q shorter than the window
        KM_CNT(2);
        for (int64_t i = 0; i < w; ++i) XT[i] = i < nq ? Q[i] : 0;
        sbn3i_sub_n(R, xw, XT, long(w));
    }
    const bool neg = R[w - 1] >> 63;
    if (neg) {                                                               // |r| = -R mod B^w (3: r < 0)
        KM_CNT(3);
        uint64_t cy = 1;
        for (int64_t i = 0; i < w; ++i) { const limb v = ~R[i] + cy; cy = cy && v == 0; R[i] = v; }
    }
    int64_t nr = w;
    while (nr && !R[nr - 1]) --nr;

    // corr = y r at grid -K-1 (r = 2 rh: corr / 2 is y rh, its error < 2 units of B^(-K-1))
    fxr rc{0, 0};
    if (!nr) KM_CNT(4);                                                      // 4: r = 0
    if (nr) {
        const fx rr{R, gq + nr, uint64_t(nr) | (neg ? fp::sign_bit : 0)};
        rc = product(C, y, rr, -K - 1, f);
    }
    const int64_t nc = fp::len(rc.ns), gc = rc.e - nc;

    // z = s0 + corr / 2 at positions -K .. -1 (top: position 0); corr / 2 cut to grid -K: digit j = bits 1..64 of C's
    // limb j + d, d = -K - gc (one shift pass, then the scalar add / sub)
    if (g0 + K > 0) memset(z, 0, size_t(8 * (g0 + K)));
    if (g0 + n0 < 0) memset(z + g0 + n0 + K, 0, size_t(8 * -(g0 + n0)));    // above s0's top (s0 < B^-1)
    limb top = 0;
    if (g0 + n0 > 0) KM_CNT(5), top = s0d[n0 - 1], memcpy(z + g0 + K, s0d, size_t(8 * (n0 - 1)));   // position 0: s0 >= 1
    else memcpy(z + g0 + K, s0d, size_t(8 * n0));
    bool over = top != 0, under = false;
    const int64_t d = -K - gc, m = nc - d;
    if (m > 0) {
        for (int64_t j = 0; j + 1 < m; ++j) C[j] = (C[j + d] >> 1) | (C[j + d + 1] << 63);
        C[m - 1] = C[m - 1 + d] >> 1;
        if (!(rc.ns & fp::sign_bit)) {
            uint64_t cy = sbn3i_add_n(z, z, C, long(m));
            for (int64_t j = m; cy && j < K; ++j) cy = ++z[j] == 0;
            over = over || cy;
        } else {
            uint64_t bw = sbn3i_sub_n(z, z, C, long(m));
            for (int64_t j = m; bw && j < K; ++j) bw = z[j]-- == 0;
            if (bw) { if (top) --top; else under = true; }
            over = top != 0;
        }
    }
    // clamps into [B^(K-1), B^K - 1], where T lies (6: over, 7: under, 8: top limb zero)
    if (over) KM_CNT(6);
    else if (under) KM_CNT(7);
    else if (!z[K - 1]) KM_CNT(8);
    if (over) for (int64_t i = 0; i < K; ++i) z[i] = ~limb(0);
    else if (under || !z[K - 1]) {
        for (int64_t i = 0; i < K - 1; ++i) z[i] = 0;
        z[K - 1] = 1;
    }
}
